package com.nequard.analytics;
import com.nequard.monitoring.MetricSnapshotRepository;import org.springframework.web.bind.annotation.*;import java.util.*;
@RestController @RequestMapping("/api/v1/analytics") public class AnalyticsController{private final MetricSnapshotRepository repo;public AnalyticsController(MetricSnapshotRepository r){repo=r;}@GetMapping("/device/{deviceId}")public Map<String,Object> device(@PathVariable UUID deviceId){var rows=repo.findTop100ByDeviceIdOrderByRecordedAtDesc(deviceId);double avgCpu=rows.stream().filter(x->x.getCpuPercent()!=null).mapToDouble(x->x.getCpuPercent()).average().orElse(0);double avgMem=rows.stream().filter(x->x.getMemoryPercent()!=null).mapToDouble(x->x.getMemoryPercent()).average().orElse(0);return Map.of("samples",rows.size(),"averageCpuPercent",avgCpu,"averageMemoryPercent",avgMem);}}